class Library:
    def __init__(self):
        self.books = {}  # has-a: title -> Book
        self.members = {}  # has-a: name -> Member

    def checkout(self, name, title):
        member, book = self.members[name], self.books[title]
        if book.checked_out:
            raise ValueError(f"{title} is already out")
        if not member.can_borrow():
            raise ValueError(f"{name} is at the limit")
        book.check_out()
        member.borrow(book)

