class Item:
    def __init__(self, name, price, qty=1):
        self.name = name
        self.price = price
        self.qty = qty

    def subtotal(self):
        return self.price * self.qty

class Cart:
    def __init__(self):
        self.items = []

    def add(self, item):
        for existing in self.items:
            if existing.name == item.name:
                existing.qty += item.qty
                return
        self.items.append(item)

    def total(self):
        result = 0
        for i in self.items:
            result += i.subtotal()
        return result

cart = Cart()
cart.add(Item("pen", 2, 3))
cart.add(Item("pad", 5))
cart.add(Item("pen", 2))
